# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.33.1/ankra-cli-darwin-arm64"
      sha256 "5850e6a8a7017886f99f6df1e0834dd8fd05849df96ec06ba1a0679f58289336"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.33.1/ankra-cli-darwin-amd64"
      sha256 "5adca978b06aefe573cb482beb348ce4f305619184793793acd74195b30e7ba0"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.33.1/ankra-cli-linux-arm64"
      sha256 "e0ef6d1226618695f9aba09762b7b466bf3e2215488fca3b85aaa3ec6cc0b0f1"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.33.1/ankra-cli-linux-amd64"
